// Future: Replace this mock node with 'MongoDB Get Previous Session Answers'
const body = $json.body || {};
const sessionId = body.session_id || 'demo-session-001';
const patientId = body.patient_id || 'demo-patient-001';
const language = body.language || 'English';
const patientAnswer = body.patient_answer || '';
const questionId = body.question_id || 'q_01';

// Mock previous Q&A history
const mockPreviousAnswers = [
  {
    "question": "What is your main health problem?",
    "answer": "I have fever and cough for three days."
  }
];

return [{
  json: {
    session_id: sessionId,
    patient_id: patientId,
    language: language,
    question_id: questionId,
    patient_answer: patientAnswer,
    previous_answers: mockPreviousAnswers
  }
}];

// Rule-based Red-Flag detection & AI Prompt construction
const answer = ($json.patient_answer || '').toLowerCase();

const redFlagKeywords = [
  "chest pain", "seene me dard", "seene mein dard",
  "difficulty breathing", "saans lene me takleef", "shortness of breath",
  "unconscious", "fainted", "loss of consciousness",
  "severe bleeding", "blood loss",
  "suicide", "self-harm", "marne ka khayal"
];

let detectedRedFlag = false;
let redFlagType = "";
let redFlagMessage = "";

for (const keyword of redFlagKeywords) {
  if (answer.includes(keyword)) {
    detectedRedFlag = true;
    redFlagType = "EMERGENCY_TRIAGE_ALERT";
    redFlagMessage = "Possible urgent medical concern detected. Please seek immediate professional medical assistance.";
    break;
  }
}

const prompt = `You are MediKiosk AI, an assistive clinical history-taking engine.
Analyze the patient's latest answer in ${$json.language || 'English'}.

Patient Answer: "${$json.patient_answer}"
Previous Context: ${JSON.stringify($json.previous_answers)}

Instructions:
1. Do NOT diagnose or prescribe treatment.
2. Extract clinical facts (symptoms, duration, existing conditions, medications).
3. Formulate the SINGLE NEXT simple follow-up question in ${$json.language || 'English'}.

Return ONLY a valid JSON object matching this schema:
{
  "symptoms": ["symptom name"],
  "duration": "duration string",
  "existing_conditions": [],
  "medications": [],
  "important_information": [],
  "unclear_information": [],
  "next_question": "Your next follow-up question in ${$json.language || 'English'}"
}`;

return [{
  json: {
    ...$json,
    rule_red_flag: detectedRedFlag,
    red_flag_type: redFlagType,
    red_flag_message: redFlagMessage,
    ai_prompt: prompt
  }
}];

// Fallback & JSON Parser node for AI Output
const inputData = $input.first().json;
const bodyData = inputData.body || inputData;
const ruleRedFlag = inputData.rule_red_flag || false;
const redFlagType = inputData.red_flag_type || "";
const redFlagMessage = inputData.red_flag_message || "";

let extracted = {
  symptoms: [inputData.patient_answer],
  duration: "3 days",
  existing_conditions: [],
  medications: [],
  important_information: [],
  unclear_information: []
};
let nextQuestion = "How high has your fever been?";
let parseSuccess = true;

try {
  if (bodyData && bodyData.response) {
    const parsed = typeof bodyData.response === 'string' ? JSON.parse(bodyData.response) : bodyData.response;
    if (parsed.symptoms) extracted.symptoms = parsed.symptoms;
    if (parsed.duration) extracted.duration = parsed.duration;
    if (parsed.existing_conditions) extracted.existing_conditions = parsed.existing_conditions;
    if (parsed.medications) extracted.medications = parsed.medications;
    if (parsed.important_information) extracted.important_information = parsed.important_information;
    if (parsed.unclear_information) extracted.unclear_information = parsed.unclear_information;
    if (parsed.next_question) nextQuestion = parsed.next_question;
  }
} catch (e) {
  parseSuccess = false;
}

return [{
  json: {
    success: true,
    session_id: inputData.session_id || 'demo-session-001',
    extracted_information: extracted,
    red_flag: ruleRedFlag,
    red_flag_details: ruleRedFlag ? {
      type: redFlagType,
      message: redFlagMessage
    } : null,
    next_question: nextQuestion,
    parse_success: parseSuccess
  }
}];

const body = $json.body || {};
const fileBase64 = body.file_base64 || '';
const mimeType = body.mime_type || 'image/jpeg';
const documentId = body.document_id || 'demo-doc-' + Date.now();

// Format as Base64 Data URL (data:<mime-type>;base64,<data>)
const dataUrl = fileBase64.startsWith('data:') ? fileBase64 : `data:${mimeType};base64,${fileBase64}`;

const ocrPrompt = `Analyze this medical document image and extract clinical entities.
Rules:
1. Never invent missing medical info. Use "NOT_FOUND" or "UNCLEAR".
2. Do NOT diagnose or prescribe treatment.
3. Return strictly a JSON object matching:
{
  "document_type": "PRESCRIPTION | LAB_REPORT | DISCHARGE_SUMMARY",
  "raw_transcription": "Extracted text",
  "patient": { "name": "NOT_FOUND", "age": "NOT_FOUND", "gender": "NOT_FOUND" },
  "medicines": [ { "name": "Paracetamol", "dosage": "500mg", "frequency": "1-0-1" } ],
  "test_results": [],
  "diagnosis_or_complaint": [],
  "advice": [],
  "unclear_text": [],
  "requires_human_review": true
}`;

return [{
  json: {
    document_id: documentId,
    data_url: dataUrl,
    ocr_prompt: ocrPrompt
  }
}];

